INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('balor-of-the-poisonous-eye-ii', 'Balor of the Poisonous Eye II', NULL, 'A Fomorian god, second in command of the Fomorians', 'rifts', 'Deity (a Fomorian god, descended from the first Balor)', 'Equal to a 10th level knight/warrior (as printed)', 10, 'Miscreant', '175', '13 feet (3.9 m)', NULL, '{"IQ":12,"ME":13,"MA":11,"PS":39,"PP":23,"PE":24,"PB":8,"Spd":132}', NULL, NULL, 3300, 670, NULL, NULL, 14, '{"attacks":7,"initiative":4,"strike":9,"parry":10,"dodge":10,"roll":4,"pull":4}', 'Combat equal to hand to hand: assassin, seven attacks per melee. Critical strike on a natural 18-20. +2 to save vs psionic attack, +5 vs magic, +5 vs poison, +8 vs Horror Factor. Supernatural strength, endurance and speed; a mega-damage creature. I.S.P.: none.', '[]', 'No separate percentages; all at 90%: Hand to Hand: Assassin, Boxing, Climbing, Prowl, W.P. Sword, W.P. Knife, W.P. Targeting (throwing sticks and spears in particular), Track (humanoids), Land Navigation, Wilderness Survival, Horsemanship, Mathematics: Basic, and speaks Dragonese, Gobblely and Faerie. Newly learned, all at 50%: Radio: Basic, W.P. Energy Rifle, and speaks English/American and Euro.', 'Nightvision 1200 ft (366 m) and sees the invisible. Bio-regenerates 1D4x10 per melee. Impervious to cold and to fire, mega-damage fire included. Swims expertly and needs no air, so he can stay underwater for hours and toxic gases do not touch him. Can metamorphose into one of three black shapes: a big eel, a snake, or a fish like a serpent. His eye fires a death beam (see his attacks).', 'All spell magic of levels 1-4.', 'None.', NULL, 'None.', 'Favorite weapons: swords, spears, throwing sticks and a Triax pulse rifle (printed only so; no model is named). Scathach Magic Manacles, three pair of giant size and four of human size; 20 feet (6 m) of Scathach Magic Chains; four Scathach Magic Throwing Irons. A flaming sword doing 4D6 M.D. (printed as flaming sword; the block does not call it the TW Flaming Sword). Body armor: none, only a decorative half suit of dull black plate on arms, legs and shoulders. Vehicle: a pale white, ghostly Fomorii war-horse with glowing orange eyes and smoking nostrils, twice a horse''s size and fit for a giant; 500 M.D.C., runs at 60 mph (96 km).', 'About 100 million credits in valuables.', 'Aggressive and cruel like the first Balor and most fomorians; a dynamic fighter set on conquering the British Isles, with an eye on lands beyond them.', 'Those of Bres: a couple of dabuggh tribes in loose alliance, and enslaved goblins, orcs, humans and others. He likes and respects Bres, and the two work well together.', NULL, 'The first Balor, a giant with super powers and the god of the fomorians, was slain when they last invaded Earth some four or five thousand years ago. This one, apparently a descendant, has taken his name and his evil ways, and with Bres rules about a million fomorians (p.127)', 'Rifts World Book 3: England p.127'),
('bres-the-beautiful', 'Bres the Beautiful', NULL, 'King of the Fomorians, an ancient Celtic war-god', 'rifts', 'Deity (half Fomorian, half god of light)', 'Equal to an 11th level royal knight and psionic (as printed)', 11, 'Diabolic', NULL, 'A 20 foot giant in his natural size; shrinks at will in 1 foot (0.3 m) steps to 5 feet (1.5 m)', NULL, '{"IQ":20,"ME":25,"MA":19,"PS":41,"PP":28,"PE":28,"PB":30,"Spd":66}', NULL, NULL, 10800, 900, 200, NULL, 14, '{"attacks":8,"initiative":5,"strike":10,"parry":10,"dodge":10,"damage":10,"roll":7,"pull":5}', 'Hand to hand: expert, eight attacks per melee. The +10 damage is M.D. Critical strike on a natural 18-20. +5 to save vs psionic attack, +7 vs magic, +7 vs poison, +7 vs Horror Factor. 55% to evoke trust or intimidation, 92% to charm and impress. Supernatural P.S. and P.E. Spd 66 is 45 mph (72 km). His Horror Factor of 14 applies when he leads his fomorians into battle, or once someone grasps that he is an ancient Celtic god.', '[]', 'No separate percentages; all at 96%: Hand to Hand: Expert, Boxing, W.P. Sword, W.P. Knife, W.P. Blunt, W.P. Energy Pistol, W.P. Energy Rifle, Track Animals, Hunting (printed as hunt), Land Navigation, Wilderness Survival, Horsemanship, Mathematics: Basic, speaks and reads Dragonese, and speaks Gobblely. Newly learned, all at 60%: Pilot Hover Vehicle, Radio: Basic, and speaks English/American and Euro.', 'Changes size by thought between his natural 20 feet and 5 feet, the change lasting as long as he likes. Nightvision 1200 ft (366 m). Bio-regenerates 1D6x10 per minute.', 'His spell casting is innate and as dark as he is; 900 P.P.E., 11th level. All spell magic of levels 1-6, plus Tongues, Call Lightning, Agony, Animate/Control Dead, Dispel Magic Barriers, Invisibility: Superior, Life Drain, Hallucination, Metamorphosis: Human, Sickness, Spoil Food and Water, Speed of the Snail, Protection Circle: Simple (printed as protection: simple), Dimensional Portal and Close Rift.', '200 I.S.P., 11th level: Impervious to Cold, Impervious to Fire, Mind Block, Nightvision, See the Invisible, Resist Fatigue, Levitation, Telekinesis, Psi-Sword, Psi-Shield and Pyrokinesis.', NULL, 'None.', 'Favorite weapons: battle axes, swords, knives and high-powered energy pistols. Always carries Silver Tooth, his soul drinking rune sword with elemental powers of earth (no further figures in his block), a Vibro-Knife and a TX-22 Precision Laser Pistol (printed as Triax laser pistol: 2D4 M.D., 20 shots, 1000 ft). Body armor: dull white with gold accents, 1000 M.D.C. Vehicle: a pale white, ghostly Fomorii war-horse with glowing orange eyes and smoking nostrils, twice a horse''s size and fit for him at giant size; 600 M.D.C., runs at 60 mph (96 km).', 'A fortune in gems and gold, about 500 million credits.', 'Fair of face and a superb fighter, but cold-hearted: selfish, greedy, cruel and vengeful. He has let his hatred of Lugh fester for ages and wants their next meeting to be a fight to the death. This time he moves slowly, entrenching his fomorians before reaching for more than he can hold.', 'Balor of the Poisonous Eye II, his second in command. Loose alliances with a couple of dabuggh tribes; enslaved goblins, orcs, humans and others serve him. For now he and his legion lean on natural powers and magic, but robots and energy weapons intrigue them.', 'Lugh, who beat him long ago and drove the Fomorii from Earth.', 'A Celtic war-god king who, long before the Rifts, led the Fomorians against Scotland and Ireland and ruled them harshly; the book blames him for stripping the Highland forests to bare rock. Lugh defeated him and sent the Fomorii home but let him live. Back on the transformed Earth, he opened a rift a century ago and brought the fomorians through. Pronounced Breaze (p.127-128)', 'Rifts World Book 3: England p.127-128'),
('lugh-the-shining-one', 'Lugh The Shining One', NULL, 'A great warrior god of the ancient Celts', 'rifts', 'Deity', 'Equal to a 13th level ley line walker and psionic (as printed)', 13, 'Scrupulous', NULL, 'A 20 foot giant in his natural size; shrinks at will in 1 foot (0.3 m) steps to 6 feet (1.8 m)', NULL, '{"IQ":23,"ME":24,"MA":27,"PS":50,"PP":24,"PE":24,"PB":22,"Spd":66}', NULL, NULL, 16300, 1200, 333, NULL, 14, '{"attacks":9,"initiative":6,"strike":10,"parry":12,"dodge":12,"roll":6,"pull":6}', 'Hand to hand: expert, nine attacks per melee. Critical strike on a natural 18-20. +5 to save vs psionic attack, +5 vs magic, +5 vs poison, +10 vs Horror Factor. 92% to evoke trust or intimidation, 60% to charm and impress. Supernatural P.S. and P.E. Printed as a Horror/awe Factor. Spd 66 running (45 mph, 72 km) or 293 flying (200 mph, 321 km).', '[]', 'No separate percentages; all at 98%: Hand to Hand: Expert, W.P. Sword, W.P. Knife, every wilderness skill, Botany (printed botony), Astronomy, Mathematics: Basic and Advanced, Holistic Medicine, speaks and reads Dragonese and English, and speaks Gobblely and Faerie.', 'Glows always with a warm, sunlike light, dimmed with age until someone in sunglasses can look at him and make out his face. Changes size by thought between his natural 20 feet and 6 feet, the change lasting as long as he likes, and can metamorphose into an animal (birds of prey and big-antlered deer by preference). Nightvision 1200 ft (366 m), hawk-keen ordinary sight, bio-regenerates 1D6x10 per minute, flies at 200 mph (321 km), and fires a laser-like beam (see his attacks).', '1200 P.P.E. All spell magic of levels 1-8, plus Metamorphosis: Animal, Protection Circle: Simple, Protection Circle: Superior, Calm Storms, Time Hole, Dimensional Portal and Close Rift.', '333 I.S.P., 13th level: every healing power, Levitation, Mind Block Auto-Defense, P.P.E. Shield, Telekinesis (Super) and Psi-Sword.', NULL, 'None.', 'None; he relies on magic or his psi-sword. Body armor: none. Vehicle: none.', 'Gems and precious metals worth easily 500 million credits.', 'Sworn to shield the people of Earth from the fomorian hordes and their king. At first he hides his return from Bres, disguised in animal form, or maybe as a star child, while he learns about the fomorians and protects humanoids from them; when the invasion comes he means to lead the defense.', 'The Gods of Light; he works with or aids any creature of good alignment.', 'Bres the Beautiful and his fomorians.', 'One of the great Celtic warrior gods, said once to shine as bright as the sun. Ages ago he beat Bres and drove the Fomorii out, but spared him. Now old and dimmer, though still somewhat stronger than Bres, he has lately heard of the fomorian push into northern Scotland and come back to Earth. Pronounced Loo (p.127, 129)', 'Rifts World Book 3: England p.129'),
('dagda', 'Dagda', NULL, 'The All Father', 'rifts', 'Deity', 'Equal to a 15th level line walker, stone master and woodland druid (as printed)', 15, 'Anarchist (once Scrupulous)', NULL, 'A 24 foot (7.3 m) giant in his natural size; shrinks at will in 1 foot (0.3 m) steps to 6 feet (1.8 m)', NULL, '{"IQ":28,"ME":20,"MA":26,"PS":60,"PP":28,"PE":30,"PB":20,"Spd":80}', NULL, NULL, 19030, 5000, 1000, NULL, 19, '{"attacks":10,"initiative":4,"strike":9,"parry":12,"dodge":12,"damage":20,"roll":6,"pull":6}', 'Hand to hand: expert, ten attacks per melee. The +20 damage is M.D. Critical strike on a natural 17-20. +5 to save vs psionic attack, +8 vs magic, +10 vs Horror Factor; impervious to poison. 88% to evoke trust or intimidation, 50% to charm or impress. Supernatural P.S. and P.E. His Horror Factor of 19 applies once someone grasps that he is an ancient Celtic god.', '[]', 'No separate percentages; all at 98%: Hand to Hand: Expert, W.P. Sword, W.P. Blunt, W.P. Energy Pistol, W.P. Energy Rifle, Astronomy, Botany, Holistic Medicine, Herbology, Mathematics: Basic and Advanced, every wilderness skill, Wilderness Survival, Horsemanship, speaks and reads Dragonese, and speaks Faerie and Gobblely.', 'Changes size by thought between his natural 24 feet and 6 feet, the change lasting as long as he likes. Nightvision 1200 ft (366 m). Bio-regenerates 1D6x100 per minute. Metamorphoses at will into five animal forms: eagle, swan, raven, wild boar and deer.', '5000 P.P.E. Herbology as a dryad druid has it, all spell magic, and all stone master magic.', '1000 I.S.P., as a 15th level Mind Melter: every sensitive and every super psionic power.', NULL, 'None.', 'Favorite weapons: war hammers, maces and clubs; he will have nothing to do with machines or technology. Five magic items. 1. The Staff of Dagda (printed name; no catalog row holds it, and the held Dagda''s Scepter rows are Book of Magic herb preparations, not this staff): a wooden staff 25 feet (7.6 m) tall whose claw-shaped head serves as a barbed club, a black jewel in the claw firing colored beams (see his attacks; a white beam undoes petrification or purifies food and water), and a lower claw gripping a crystal ball through which he watches people and places he knows. Its foot, touched to someone, heals 1D6x10 hit points and S.D.C. (M.D.C. for a mega-damage being), negates poison, and restores and resurrects as the Millennium staff of life does, three times a day. 2. Amulet of Fire, a dark red jewel: casts every fire spell of the Rifts RPG (not fire elemental spells) three times a day, and holds three minor fire elementals he can release and recall; one slain is gone from it. 3. A pouch of 30 magical herbs and 12 magic potions. 4. Murii Magwa the Magic Harp: an 8 foot (2.4 m) magic rune harp, I.Q. 11, anarchist, indestructible, that moves itself as if by telekinesis. It hates fomorians, who once stole and mistreated it, and kills them on sight, and it enjoys making trouble for humans and others. Its music so relaxes listeners that they are -3 on initiative, lose one melee action and miss much of what goes on, for the first melee round of an attack only. It fights on its own with five attacks per melee (see his attacks). 5. Dagda''s Cauldron of Plenty: works as a Scathach Magic Cauldron of Plenty does, making ten times the food put in, but it stands 10 feet tall and holds up to 2000 gallons or 14,000 lbs (6300 kg). Body armor: none. Vehicle: none.', 'None; he seems neither to have nor to want any.', 'Perhaps insane: forgetful, easily distracted and confused, and talking to voices no one else hears. He may be kind and helpful one moment, boisterous and cruel the next, or wholly indifferent. Quick to anger when mocked or struck, and mean and merciless in a fight. He cares little for the cause of good, but slays fomorians wherever he finds them, and may become an ally or an enemy of humanoids.', 'None at present.', 'The Fomorians.', 'Once the mighty All-Father of the Celtic gods, a symbol of strength, wisdom and fertility, called the Good God and patron of druids. Now senile or schizophrenic, a wandering recluse and glutton who often goes about disguised as a human or animal. Still a master herbalist, he calls on Millennium Trees, druids and faerie folk, and keeps mostly to Scotland, northern England, Wales and Ireland. Pronounced Dag dah (p.129-131)', 'Rifts World Book 3: England p.129-131');
