-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 notable NPCs are in' AS assertion, count(*) AS got, 4 AS want
  FROM notable_npcs WHERE slug IN ('balor-of-the-poisonous-eye-ii', 'bres-the-beautiful', 'lugh-the-shining-one', 'dagda');
SELECT 'and the notables 14' AS assertion, count(*) AS got, 14 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('balor-of-the-poisonous-eye-ii', 'bres-the-beautiful', 'lugh-the-shining-one', 'dagda');

